from store import save
PRICES = {'mug': 12}


def place(item, qty):
    if item not in PRICES:
        raise ValueError(f'no such item: {item}')
    order = {'item': item, 'qty': qty, 'total': PRICES[item] * qty}
    save(order)
    return order

